import type {
  FieldControlProps,
  FieldErrorProps,
  FieldHelpTextProps,
  FieldLabelProps,
  FieldProps,
  FieldSubtextProps,
  FieldHelpTextTooltipProps,
  FieldHelpTextPopoverProps,
} from "./field.types";

import React, { forwardRef } from "react";
import { Attention as AttentionIcon, Help as HelpIcon } from "@exp-textura/icons";
import { Tooltip } from "@components/tooltip";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import {
  Controller,
  useFormContext,
  useFormState,
  type ControllerRenderProps,
} from "react-hook-form";
import { useFormSize } from "@components/form/hooks/use-form-size";
import { Popover } from "@components/popover";

import { FieldClasses, StyledField } from "./field.styles";
import { FieldContext, useField } from "./hooks/use-field";
import { useFieldSharedLogic } from "./hooks/use-field-shared-logic";

// This component renders the UI and is used by both the connected and standalone versions.
const FieldRenderer = forwardRef<
  HTMLDivElement,
  FieldProps & ReturnType<typeof useFieldSharedLogic>
>((props, ref) => {
  const { children, name, contextValue, rootClasses, controlPlacement, ...rest } = props;
  const theme = useTheme();

  const childrenArray = React.Children.toArray(children);

  const labelChildren = childrenArray.filter(
    (child) =>
      React.isValidElement(child) &&
      (child.type as { displayName?: string }).displayName === FieldLabel.displayName,
  );

  const subtextChildren = childrenArray.filter(
    (child) =>
      React.isValidElement(child) &&
      (child.type as { displayName?: string }).displayName === Subtext.displayName,
  );

  const controlChildren = childrenArray.filter(
    (child) =>
      React.isValidElement(child) &&
      (child.type as { displayName?: string }).displayName === Control.displayName,
  );

  const otherChildren = childrenArray.filter(
    (child) =>
      !React.isValidElement(child) ||
      (labelChildren.indexOf(child) === -1 &&
        controlChildren.indexOf(child) === -1 &&
        subtextChildren.indexOf(child) === -1),
  );

  return (
    <FieldContext.Provider value={contextValue}>
      <StyledField ref={ref} className={rootClasses} currentTheme={theme} name={name} {...rest}>
        <div
          className={clsx(FieldClasses.main, {
            [FieldClasses.controlPlacementInline]: controlPlacement === "inline",
            [FieldClasses.controlPlacementInlineTrailing]: controlPlacement === "inlineTrailing",
          })}
        >
          {labelChildren}
          {subtextChildren}
          {controlChildren}
        </div>
        {otherChildren}
      </StyledField>
    </FieldContext.Provider>
  );
});
FieldRenderer.displayName = "FieldRenderer";

// This version is rendered when a form context is available.
const FieldConnected = forwardRef<HTMLDivElement, FieldProps>((props, ref) => {
  const formState = useFormState({ name: props.name });
  const logic = useFieldSharedLogic(props, formState);
  return <FieldRenderer {...props} {...logic} ref={ref} />;
});
FieldConnected.displayName = "FieldConnected";

// This version is rendered when no form context is available.
const FieldStandalone = forwardRef<HTMLDivElement, FieldProps>((props, ref) => {
  const logic = useFieldSharedLogic(props, null);
  return <FieldRenderer {...props} {...logic} ref={ref} />;
});
FieldStandalone.displayName = "FieldStandalone";

// The main Field component decides which version to render.
const Field = forwardRef<HTMLDivElement, FieldProps>((props, ref) => {
  const formContext = useFormContext();
  const formSizeHook = useFormSize();
  const formSize = props.formSize ?? formSizeHook?.formSize;

  const newProps = { ...props, formSize };

  return formContext ? (
    <FieldConnected {...newProps} ref={ref} />
  ) : (
    <FieldStandalone {...newProps} ref={ref} />
  );
});
Field.displayName = "Field";

const fieldsWithoutRequired = ["Button", "CheckboxGroup", "IconButton", "Slider"];
const fieldsLabelledBy = ["MultiSelect"];
const Control = ({ children, className, style, ...props }: FieldControlProps) => {
  const {
    name,
    rules,
    inputId,
    labelId,
    ariaDescribedBy,
    isInvalid,
    formSize,
    required,
    disabled,
  } = useField();
  const formContext = useFormContext();

  const renderControl = (field: ControllerRenderProps) => {
    const element = children(field);
    const displayName = (element.type as { displayName?: string }).displayName;
    const sizeProp =
      displayName === "Input" || displayName === "Select"
        ? { inputSize: formSize }
        : { size: formSize };
    const ariaRequired =
      required && !fieldsWithoutRequired.includes(String(displayName)) ? "true" : undefined;
    const ariaLabelledBy = fieldsLabelledBy.includes(String(displayName)) ? labelId : undefined;

    return (
      <div className={FieldClasses.controlContainer}>
        {React.cloneElement(element, {
          ...props,
          ...field,
          required,
          disabled,
          id: inputId,
          ...sizeProp,
          "aria-describedby": ariaDescribedBy,
          "aria-required": ariaRequired,
          "aria-labelledby": ariaLabelledBy,
          "aria-invalid": isInvalid ? "true" : undefined,
          variant: isInvalid ? "critical" : element.props.variant,
          className: clsx(element.props.className, className),
          style: { ...element.props.style, ...style },
        })}
      </div>
    );
  };

  if (!formContext) {
    const fieldLike = {
      name,
      value: undefined,
      onChange: () => {},
      onBlur: () => {},
      ref: () => {},
    };
    return renderControl(fieldLike);
  }

  return (
    <Controller
      control={formContext.control}
      name={name}
      render={({ field }) => renderControl(field)}
      rules={rules}
    />
  );
};
Control.displayName = "Field.Control";

const FieldLabel = ({ className, ...props }: FieldLabelProps) => {
  const { inputId, labelId, required, disabled } = useField();

  const childrenArray = React.Children.toArray(props.children);
  const helpTooltip = childrenArray.find(
    (child) =>
      React.isValidElement(child) &&
      (child.type as { displayName?: string }).displayName === HelpTextTooltip.displayName,
  );

  const otherChildren = childrenArray.filter(
    (child) =>
      !React.isValidElement(child) ||
      (child.type as { displayName?: string }).displayName !== HelpTextTooltip.displayName,
  );

  return (
    <label
      className={clsx(FieldClasses.label, { [FieldClasses.labelDisabled]: disabled }, className)}
      htmlFor={inputId}
      id={labelId}
      {...props}
    >
      {otherChildren}
      {required && <span className={FieldClasses.requiredIndicator}>*</span>}
      {helpTooltip}
    </label>
  );
};
FieldLabel.displayName = "Field.Label";

const Error = ({ className, children, showIcon = true, icon, ...props }: FieldErrorProps) => {
  const { isInvalid, error, errorId } = useField();

  if (!isInvalid) {
    return null;
  }

  return (
    <span className={clsx(FieldClasses.error, className)} id={errorId} {...props}>
      {showIcon && (icon || <AttentionIcon />)}
      {children || error?.message}
    </span>
  );
};
Error.displayName = "Field.Error";

const HelpText = ({ children, className, ...props }: FieldHelpTextProps) => {
  const { helpTextId } = useField();

  return (
    <span className={clsx(FieldClasses.helpText, className)} id={helpTextId} {...props}>
      {children}
    </span>
  );
};
HelpText.displayName = "Field.HelpText";

const Subtext = ({ children, className, ...props }: FieldSubtextProps) => {
  const { subtextId } = useField();

  return (
    <span className={clsx(FieldClasses.subtext, className)} id={subtextId} {...props}>
      {children}
    </span>
  );
};
Subtext.displayName = "Field.Subtext";

const HelpTextTooltip = ({ children, icon, ...props }: FieldHelpTextTooltipProps) => {
  return (
    <Tooltip {...props}>
      <Tooltip.Trigger>
        <span className={FieldClasses.helpTextTooltipTrigger}>{icon || <HelpIcon />}</span>
      </Tooltip.Trigger>
      <Tooltip.Content>{children}</Tooltip.Content>
    </Tooltip>
  );
};
HelpTextTooltip.displayName = "Field.HelpTextTooltip";

const HelpTextPopover = ({ children, icon, ...props }: FieldHelpTextPopoverProps) => {
  return (
    <Popover dismissable={true} {...props}>
      <Popover.Trigger>
        <span className={FieldClasses.helpTextPopoverTrigger}>{icon || <HelpIcon />}</span>
      </Popover.Trigger>
      <Popover.Content>{children}</Popover.Content>
    </Popover>
  );
};
HelpTextTooltip.displayName = "Field.HelpTextTooltip";

type FieldCompoundComponent = typeof Field & {
  Control: typeof Control;
  Label: typeof FieldLabel;
  Error: typeof Error;
  HelpText: typeof HelpText;
  HelpTextTooltip: typeof HelpTextTooltip;
  HelpTextPopover: typeof HelpTextPopover;
  Subtext: typeof Subtext;
};

const FieldRoot = Field as FieldCompoundComponent;

FieldRoot.Control = Control;
FieldRoot.Label = FieldLabel;
FieldRoot.Error = Error;
FieldRoot.HelpText = HelpText;
FieldRoot.HelpTextTooltip = HelpTextTooltip;
FieldRoot.HelpTextPopover = HelpTextPopover;
FieldRoot.Subtext = Subtext;

export default FieldRoot;
